<?php if($latest): ?><script>
(() => {
 const slider=document.querySelector('[data-news-slider]'); if(!slider)return;
 const items=<?= json_encode(array_map(static fn($p)=>['title'=>$p['title'],'excerpt'=>excerpt_text((string)$p['excerpt'],190),'category'=>($p['category']??'Notícia').' · '.date('d/m/Y',strtotime($p['published_at'])),'image'=>!empty($p['cover_image'])?'../'.$p['cover_image']:'https://images.unsplash.com/photo-1541888946425-d81bb19240f5?auto=format&fit=crop&w=1200&q=80','url'=>'post.php?slug='.$p['slug']],$latest),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>;
 let index=0;const title=slider.querySelector('[data-slider-title]'),excerpt=slider.querySelector('[data-slider-excerpt]'),category=slider.querySelector('[data-slider-category]'),image=slider.querySelector('[data-slider-image]'),link=slider.querySelector('[data-slider-link]');
 function show(next){index=(next+items.length)%items.length;const item=items[index];title.textContent=item.title;excerpt.textContent=item.excerpt;category.textContent=item.category;image.src=item.image;image.alt=item.title;link.href=item.url;}
 slider.querySelector('[data-slider-prev]').addEventListener('click',()=>show(index-1));slider.querySelector('[data-slider-next]').addEventListener('click',()=>show(index+1));
 if(items.length>1 && !window.matchMedia('(prefers-reduced-motion: reduce)').matches){let timer=null,paused=false;const pause=slider.querySelector('[data-slider-pause]');const start=()=>{if(!paused&&!timer)timer=setInterval(()=>show(index+1),6500)};const stop=()=>{if(timer){clearInterval(timer);timer=null}};start();slider.addEventListener('mouseenter',stop);slider.addEventListener('focusin',stop);slider.addEventListener('mouseleave',start);slider.addEventListener('focusout',start);pause.addEventListener('click',()=>{paused=!paused;pause.setAttribute('aria-pressed',paused?'true':'false');pause.setAttribute('aria-label',paused?'Retomar rotação automática':'Pausar rotação automática');pause.innerHTML=paused?'<i class="bi bi-play-fill"></i>':'<i class="bi bi-pause-fill"></i>';if(paused)stop();else start();});}else{const pause=slider.querySelector('[data-slider-pause]');if(pause)pause.hidden=true;}
})();
</script><?php endif; ?><script>document.querySelectorAll('[data-share]').forEach(a=>{const u=encodeURIComponent(location.href);const t=encodeURIComponent(document.title);const k=a.dataset.share;const urls={facebook:'https://www.facebook.com/sharer/sharer.php?u='+u,whatsapp:'https://wa.me/?text='+t+'%20'+u,linkedin:'https://www.linkedin.com/sharing/share-offsite/?url='+u,x:'https://twitter.com/intent/tweet?url='+u+'&text='+t};a.href=urls[k]||'#';a.target='_blank';a.rel='noopener noreferrer';});</script><?php include __DIR__ . '/../../app/cookie-consent.php'; ?></body></html>
